const load = (name) => {
  if (!Object.hasOwn(fixtures, name)) throw new Error(`Unknown fixture: ${name}`);
  return fixtures[name];
};
const play = (name, opts, st) => {
  st = st || C.defaultState('sess');
  for (const ev of load(name)) C.reduce(st, ev, opts);
  return st;
};

