test('compression run: model, context, compression count, receipt', () => {
  const st = play('compression');
  assert.equal(st.main.model, 'claude-opus-5-5');
  assert.equal(st.main.provider, 'anthropic');
  assert.equal(st.main.compressions, 1);
  assert.equal(st.main.ctxWindow, 1000000);
  assert.equal(st.main.compressAt, 256000);
  assert.ok(st.main.ctxTokens > 0);
  assert.ok(st.main.costUsd > 0);
  assert.equal(st.main.isRunning, false);
  assert.ok(st.receipt, 'receipt after done');
  assert.equal(st.receipt.status, 'complete');
  assert.equal(st.receipt.tools, 88);
  const g = C.gateSummary(st);
  assert.equal(g.ran + g.error + g.denied + g.approved, 88, 'every tool settled');
  assert.equal(g.pending, 0);
  assert.ok(st.gate.recent.every((c) => c.status !== 'running'));
});

test('approval that was granted: amber then blue', () => {
  const evs = load('approval');
  const st = C.defaultState('s');
  let sawPending = false;
  for (const ev of evs) {
    C.reduce(st, ev);
    if (ev.event === 'approval') {
      sawPending = st.gate.recent.some((c) => c.status === 'pending');
      assert.equal(C.gateSummary(st).pending, 1);
    }
  }
  assert.ok(sawPending);
  assert.equal(C.gateSummary(st).pending, 0);
  assert.ok(C.gateSummary(st).approved >= 1);
});

test('approval that timed out: BLOCKED becomes denied', () => {
  const st = play('approval-blocked');
  const g = C.gateSummary(st);
  assert.ok(g.denied >= 1, JSON.stringify(g));
  assert.ok(st.log.some((l) => l.text.includes('denied')));
});

test('background delegate_task: two agent cards with goals and subagent ids', () => {
  const st = play('delegate-background');
  const cards = st.agents.filter((a) => a.via === 'stream');
  assert.equal(cards.length, 2);
  assert.match(cards[0].goal, /Part A/);
  assert.match(cards[1].goal, /Part B/);
  assert.ok(cards.every((c) => c.background && c.status === 'running'));
  assert.deepEqual(cards.map((c) => c.subagentId), ['sa-0-05713679', 'sa-1-69b80df7']);
  assert.equal(st.receipt.agents, 2);
});

test('child sessions attach to stream cards and settle them', () => {
  const st = play('delegate-background');
  const spawnAt = st.agents[0].startedAt;
  const rows = [
    { session_id: 'c1', parent_session_id: 'P', raw_source: 'subagent', model: 'claude-sonnet-5-5',
      message_count: 94, created_at: spawnAt / 1000 + 2, updated_at: spawnAt / 1000 + 900, is_streaming: false },
    { session_id: 'c2', parent_session_id: 'P', raw_source: 'subagent', model: 'claude-sonnet-5-5',
      message_count: 145, created_at: spawnAt / 1000 + 3, updated_at: spawnAt / 1000 + 4000, is_streaming: false },
    { session_id: 'other', parent_session_id: 'Q', raw_source: 'subagent', created_at: 1 },
  ];
  C.mergeChildSessions(st, rows, 'P', spawnAt + 5_000_000);
  assert.equal(st.agents.length, 2, 'no extra card for an unrelated child');
  assert.deepEqual(st.agents.map((a) => a.sessionId), ['c1', 'c2']);
  assert.ok(st.agents.every((a) => a.status === 'completed' && a.endedAt));
  assert.equal(st.agents[1].steps, 145);
  // A still-updating child is running.
  C.mergeChildSessions(st, [{ ...rows[0], updated_at: (spawnAt + 5_000_000) / 1000 - 10 }], 'P', spawnAt + 5_000_000);
  assert.equal(st.agents[0].status, 'running');
});

