test('persistence tiers shrink copies; the minimal tier really drops zero-length tails', () => {
  const st = C.defaultState('s');
  for (let i = 0; i < 100; i++) {
    st.log.push({at: i, text: 'x'.repeat(140)});
    st.gate.recent.push({tool: 'terminal', detail: 'x'.repeat(90)});
    st.advisor.consults.push({at: i});
    st.seen['stream-' + i] = i;
  }
  const before = JSON.stringify(st);
  const sizes = [0, 1, 2].map(level => JSON.stringify(C.slimForSave(st, level)).length);
  assert.ok(sizes[0] > sizes[1] && sizes[1] > sizes[2]);
  const minimal = C.slimForSave(st, 2);
  assert.deepEqual(minimal.log, []);
  assert.deepEqual(minimal.gate.recent, []);
  assert.deepEqual(minimal.advisor.consults, []);
  assert.equal(Object.keys(minimal.seen).length, 3);
  assert.equal(JSON.stringify(st), before, 'saving must not truncate the live state');
});

